import { NgModule } from '@angular/core';
import { AdminGuard } from 'src/app/guard/admin-guard';
import { AuthGuard } from 'src/app/guard/auth-guard';
import { RouterModule, Routes } from '@angular/router';
import { TabsPage } from './tabs.page';

const routes: Routes = [
  {
    path: '',
    component: TabsPage,
    children: [
      {
        path: 'home',
        loadChildren: () =>
          import('../../home/home.module').then((m) => m.HomePageModule),
      },
      {
        path: 'tickets',
        loadChildren: () =>
          import('../tickets/tickets.module').then((m) => m.TicketsPageModule),
      },
      {
        path: 'winners',
        loadChildren: () =>
          import('../winners/winners.module').then((m) => m.WinnersPageModule),
      },
      {
        path: 'referral',
        loadChildren: () =>
          import('../referral/referral.module').then(
            (m) => m.ReferralPageModule,
          ),
      },
      {
        path: 'profile',
        loadChildren: () =>
          import('../profile/profile.module').then((m) => m.ProfilePageModule),
      },

      {
        path: 'edit-profile',
        loadChildren: () =>
          import('../edit-profile/edit-profile.module').then(
            (m) => m.EditProfilePageModule,
          ),
      },
      {
        path: 'raffle-details/:id',
        loadChildren: () =>
          import('../raffle-details/raffle-details.module').then(
            (m) => m.RaffleDetailsPageModule,
          ),
      },
      {
        path: 'payment-confirmation',
        loadChildren: () =>
          import('../payment-confirmation/payment-confirmation.module').then(
            (m) => m.PaymentConfirmationPageModule,
          ),
      },
      {
        path: 'notifications',
        loadChildren: () =>
          import('../notifications/notifications.module').then(
            (m) => m.NotificationsPageModule,
          ),
      },
      {
        path: 'participations',
        loadChildren: () =>
          import('../participations/participations.module').then(
            (m) => m.ParticipationsPageModule,
          ),
      },
      {
        path: 'ticket-details/:raffleId',
        loadChildren: () =>
          import('../ticket-details/ticket-details.module').then(
            (m) => m.TicketDetailsPageModule,
          ),
      },

      {
        path: 'admin/create-raffle',
        canActivate: [AdminGuard],
        loadChildren: () =>
          import('../admin/create-raffle/create-raffle.module').then(
            (m) => m.CreateRafflePageModule,
          ),
      },

      {
        path: 'all-raffles',
        canActivate: [AuthGuard],
        loadChildren: () =>
          import('../../pages/all-raffles/all-raffles.module').then(
            (m) => m.AllRafflesPageModule,
          ),
      },

      {
        path: 'change-password',
        canActivate: [AuthGuard],
        loadChildren: () =>
          import('../change-password/change-password.module').then(
            (m) => m.ChangePasswordPageModule,
          ),
      },

      {
        path: 'responsible-play',
        canActivate: [AuthGuard],
        loadChildren: () =>
          import('../responsible-play/responsible-play.module').then(
            (m) => m.ResponsiblePlayPageModule,
          ),
      },

      { path: '', redirectTo: 'home', pathMatch: 'full' },
    ],
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class TabsPageRoutingModule {}
